import { FlatList, Text } from 'react-native';

type Produk = {
  id: string;
  nama: string;
  harga: number;
  stok: number;
};

export function DaftarProduk({ produkList }: { produkList: Produk[] }) {
  return (
    <FlatList
      data={produkList}
      keyExtractor={(produk) => produk.id}
      renderItem={({ item }) => (
        // `item` otomatis bertipe Produk — hasil inferensi dari `data`
        <KartuProduk nama={item.nama} harga={item.harga} />
      )}
    />
  );
}

