import { FlatList, View, Text } from 'react-native';

type Transaksi = {
  id: number;          // dari database, bertipe angka
  judul: string;
  nominal: number;
  tanggal: string;
};

export function RiwayatTransaksi({ data }: { data: Transaksi[] }) {
  return (
    <FlatList
      data={data}
      keyExtractor={(item) => String(item.id)}   // wajib string
      renderItem={({ item }) => (
        <View style={{ paddingVertical: 12 }}>
          <Text>{item.judul}</Text>
          <Text>Rp {item.nominal.toLocaleString('id-ID')}</Text>
        </View>
      )}
      ItemSeparatorComponent={() => (
        <View style={{ height: 1, backgroundColor: '#e5e7eb' }} />
      )}
      ListEmptyComponent={() => (
        <Text style={{ textAlign: 'center', padding: 32, color: '#6b7280' }}>
          Belum ada transaksi bulan ini
        </Text>
      )}
      ListHeaderComponent={<Text style={{ fontWeight: '600' }}>Agustus 2026</Text>}
      contentContainerStyle={{ padding: 16 }}
    />
  );
}

import { FlatList, ActivityIndicator } from 'react-native';

type Props = {
  produk: Produk[];
  sedangMuat: boolean;
  onMuatLagi: () => void;
  onSegarkan: () => void;
};

export function DaftarTakTerbatas({ produk, sedangMuat, onMuatLagi, onSegarkan }: Props) {
  return (
    <FlatList
      data={produk}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => <KartuProduk nama={item.nama} harga={item.harga} />}
      onEndReached={onMuatLagi}
      onEndReachedThreshold={0.5}          // number, bukan '0.5'
      refreshing={sedangMuat}              // boolean
      onRefresh={onSegarkan}
      ListFooterComponent={sedangMuat ? <ActivityIndicator /> : null}
    />
  );
}

