import { SectionList, View, Text } from 'react-native';

type Pesanan = {
  id: string;
  namaToko: string;
  total: number;
};

type KelompokPesanan = {
  title: string;       // nama field ini sudah ditentukan SectionList
  data: Pesanan[];     // begitu juga yang ini
};

const kelompok: KelompokPesanan[] = [
  {
    title: 'Hari ini',
    data: [
      { id: 'p1', namaToko: 'Warung Bu Tini', total: 32000 },
      { id: 'p2', namaToko: 'Kopi Senja', total: 45000 },
    ],
  },
  {
    title: 'Kemarin',
    data: [{ id: 'p3', namaToko: 'Ayam Geprek 99', total: 28000 }],
  },
];

export function RiwayatPesanan() {
  return (
    <SectionList
      sections={kelompok}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        // item bertipe Pesanan
        <Text>{item.namaToko} — Rp {item.total.toLocaleString('id-ID')}</Text>
      )}
      renderSectionHeader={({ section }) => (
        // section bertipe KelompokPesanan
        <View style={{ backgroundColor: '#f3f4f6', padding: 8 }}>
          <Text style={{ fontWeight: '600' }}>{section.title}</Text>
        </View>
      )}
      stickySectionHeadersEnabled
    />
  );
}

type KelompokDenganTotal = {
  title: string;
  totalHari: number;     // field tambahan milik kelompok
  data: Pesanan[];
};

<SectionList<Pesanan, KelompokDenganTotal>
  sections={kelompokDenganTotal}
  keyExtractor={(item) => item.id}
  renderItem={({ item }) => <BarisPesanan pesanan={item} />}
  renderSectionHeader={({ section }) => (
    <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
      <Text>{section.title}</Text>
      <Text>Rp {section.totalHari.toLocaleString('id-ID')}</Text>
      {/* section.totalHari dikenali karena generic keduanya ditulis */}
    </View>
  )}
/>
